SELECT * FROM sys_attendance_record
WHERE is_deleted = 0

    AND clock_date >= #{queryVo.startDate}


    AND clock_date <= #{queryVo.endDate}


    AND clock_type = #{queryVo.clockType}


    AND status = #{queryVo.status}


    AND user_id = #{queryVo.userId}


    AND user_name LIKE CONCAT('%', #{queryVo.userName}, '%')

ORDER BY clock_date DESC, clock_type ASC

